package lk.sliit.nutricare.diet;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity@Table(name="progress_logs")public class ProgressLog{@Id private UUID id;@Column(nullable=false,length=16)private String patientId;private UUID dietPlanId;@Column(nullable=false)private LocalDate logDate;private BigDecimal weightKg;private BigDecimal bmi;private Integer waterGlasses;private Integer mealsCompleted;@Column(nullable=false)private Instant createdAt;protected ProgressLog(){}public ProgressLog(String p,UUID plan,LocalDate date,BigDecimal w,BigDecimal bmi,Integer water,Integer meals){id=UUID.randomUUID();patientId=p;dietPlanId=plan;logDate=date;weightKg=w;this.bmi=bmi;waterGlasses=water;mealsCompleted=meals;createdAt=Instant.now();}public UUID getId(){return id;}public String getPatientId(){return patientId;}public UUID getDietPlanId(){return dietPlanId;}public LocalDate getLogDate(){return logDate;}public BigDecimal getWeightKg(){return weightKg;}public BigDecimal getBmi(){return bmi;}public Integer getWaterGlasses(){return waterGlasses;}public Integer getMealsCompleted(){return mealsCompleted;}}
